<main class="container py-5"><div class="dashboard-head"><div><span class="eyebrow">COACH</span><h1 class="fw-bold">Messages de contact</h1></div><a href="/coach" class="btn btn-outline-dark">Dashboard</a></div><div class="row g-3"><?php foreach($items as $x): ?><div class="col-lg-6"><div class="form-card h-100"><div class="d-flex justify-content-between"><strong><?=e($x['subject'])?></strong><span class="badge text-bg-<?=$x['status']==='new'?'warning':'success'?>"><?=e($x['status'])?></span></div><small><?=e($x['name'])?> · <?=e($x['email'])?></small><p class="mt-3"><?=nl2br(e($x['message']))?></p><?php if($x['status']==='new'): ?><form method="post" action="/coach/contacts/processed"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-sm btn-dark">Marquer traité</button></form><?php endif; ?></div></div><?php endforeach; ?></div></main>